func TestBackgroundPanicRecovery(t *testing.T) {
	panicked := false
	mu := sync.Mutex{}
	bg := concurrent.NewBackground(4, 1, func(r any) {
		mu.Lock()
		panicked = true
		mu.Unlock()
	})
	ok := bg.Submit(func() {
		panic("boom")
	})
	test.AssertEqual(t, ok, true)
	bg.Stop()
	mu.Lock()
	test.AssertEqual(t, panicked, true)
	mu.Unlock()
}

